package com.capybee.engine.generation.blueprint.json;

import com.capybee.engine.generation.PhaseKind;
import com.capybee.engine.generation.blueprint.*;
import com.capybee.engine.generation.blueprint.ParsedGameBlueprint.*;
import com.capybee.engine.generation.profile.*;
import com.capybee.engine.rules.ResultClass;
import java.nio.ByteBuffer;
import java.nio.charset.*;
import java.util.*;
import java.util.regex.Pattern;
import tools.jackson.core.StreamReadFeature;
import tools.jackson.databind.*;
import tools.jackson.databind.json.JsonMapper;

/** Strict local parser for the untrusted blueprint wire contract. */
public final class BlueprintOutputParser {
    private static final int MAX_BYTES=262_144,MAX_CHARS=131_072,MAX_NODES=12_000,MAX_DEPTH=32;
    private static final Pattern SYMBOL=Pattern.compile("[a-z][a-z0-9-]{0,47}");
    private static final Pattern ACTIVE=Pattern.compile("(?is)<\\s*/?\\s*(script|html|iframe|img|svg)\\b|javascript:|\\$\\{[^}]*}|\\{\\{[^}]*}}");
    private static final Set<String> CONDITION_TYPES=Set.of("COUNTER_AT_LEAST","COUNTER_AT_MOST","COUNTER_EQUALS","FLAG_IS","SET_CONTAINS","SET_SIZE_AT_LEAST","VISITED_SCENE","ALL","ANY","NOT");
    private static final Set<String> EFFECT_TYPES=Set.of("COUNTER_ADD","COUNTER_SET","FLAG_SET","SET_ADD","SET_REMOVE");
    private static final JsonMapper JSON=JsonMapper.builder().enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION)
            .enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();

    public BlueprintParseResult parse(byte[] response,ValidatedGeneratorProfile profile,ResolvedGamePreferences prefs,EffectiveGenerationConstraints limits){
        if(response==null||response.length>MAX_BYTES)return fail("BLUEPRINT_SIZE_LIMIT","", "Blueprint exceeds the supported size");
        try{return parse(StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(response)).toString(),profile,prefs,limits);}
        catch(CharacterCodingException ex){return fail("BLUEPRINT_JSON_INVALID","","Blueprint is not valid UTF-8");}
    }
    public BlueprintParseResult parse(String response,ValidatedGeneratorProfile profile,ResolvedGamePreferences prefs,EffectiveGenerationConstraints limits){
        if(!context(profile,prefs,limits))return fail("BLUEPRINT_CONTEXT_MISMATCH","","Blueprint context does not match the validated profile");
        if(response==null||response.length()>MAX_CHARS||utf8Length(response)>MAX_BYTES)return fail("BLUEPRINT_SIZE_LIMIT","","Blueprint exceeds the supported size");
        if(response.startsWith("\uFEFF")||!validUnicode(response))return fail("BLUEPRINT_TEXT_INVALID","","Blueprint contains invalid text");
        try{
            JsonNode root=JSON.readTree(response);
            if(root==null||!root.isObject())throw bad("BLUEPRINT_JSON_INVALID","","Blueprint must be one JSON object");
            int[] nodes={0}; complexity(root,1,nodes);
            C c=new C(profile,prefs,limits);
            exact(root,"",Set.of("schemaVersion","locale","title","premise","setting","toneTags","storyPromises","actors","state","objectives","phases","startSceneId","scenes","outcomes"));
            int version=integer(root,"schemaVersion","/schemaVersion"); if(version!=1)throw bad("BLUEPRINT_SCHEMA_UNSUPPORTED","/schemaVersion","Unsupported blueprint schema version");
            String locale=text(root,"locale","/locale",1,64,false,c); if(!locale.equals(prefs.gameLocale().value()))throw bad("BLUEPRINT_LOCALE_MISMATCH","/locale","Blueprint locale does not match the selected locale");
            String title=text(root,"title","/title",1,120,true,c),premise=text(root,"premise","/premise",1,1200,true,c),setting=text(root,"setting","/setting",1,800,true,c);
            List<String> tones=texts(root,"toneTags","/toneTags",1,4,48,c),promises=texts(root,"storyPromises","/storyPromises",1,4,240,c);
            var actors=actors(reqArray(root,"actors","/actors"),c); var state=state(req(root,"state","/state"),c);
            var objectives=objectives(reqArray(root,"objectives","/objectives"),c); var phases=phases(reqArray(root,"phases","/phases"),c);
            String start=symbol(req(root,"startSceneId","/startSceneId"),"/startSceneId"); var scenes=scenes(reqArray(root,"scenes","/scenes"),c);
            var outcomes=outcomes(reqArray(root,"outcomes","/outcomes"),c);
            if(c.textTotal>24000)throw bad("BLUEPRINT_TEXT_INVALID","","Blueprint narrative text exceeds the supported limit");
            return BlueprintParseResult.accepted(new ParsedGameBlueprint(version,locale,title,premise,setting,tones,promises,actors,state,objectives,phases,start,scenes,outcomes));
        }catch(BlueprintException ex){return fail(ex.code,ex.pointer,ex.safeMessage);}
        catch(RuntimeException ex){String code=ex.getMessage()!=null&&ex.getMessage().toLowerCase(Locale.ROOT).contains("duplicate")?"BLUEPRINT_DUPLICATE_KEY":"BLUEPRINT_JSON_INVALID";return fail(code,"","Blueprint JSON is invalid");}
    }

    private static boolean context(ValidatedGeneratorProfile p,ResolvedGamePreferences r,EffectiveGenerationConstraints e){
        if(p==null||r==null||e==null||!p.identity().equals(r.profileIdentity()))return false;
        var gp=p.profile(); var cap=gp.capabilities();
        var len=gp.lengthPresets().stream().filter(x->x.id().equals(r.lengthPresetId())).findFirst().orElse(null);
        var ch=gp.challengePresets().stream().filter(x->x.id().equals(r.challengePresetId())).findFirst().orElse(null);
        return len!=null&&ch!=null&&gp.supportedLocales().contains(r.gameLocale())&&e.minStoryTransitions()==len.minStoryTransitions()
                &&e.maxStoryTransitions()==len.maxStoryTransitions()&&e.minScenes()==cap.minScenes()&&e.maxScenes()<=len.maxScenes()
                &&e.maxCounters()<=ch.maxCounters()&&e.maxFlags()<=ch.maxFlags()&&e.maxSets()<=ch.maxSets()
                &&e.maxConditionDepth()<=ch.maxConditionDepth()&&e.maxEffectsPerChoice()<=ch.maxEffectsPerChoice()
                &&ch.allowedConditions().containsAll(e.allowedConditions())&&ch.allowedEffects().containsAll(e.allowedEffects());
    }
    private static List<Actor> actors(JsonNode a,C c){range(a,c.cap.minActors(),Math.min(12,c.cap.maxActors()),"/actors");List<Actor> out=new ArrayList<>();Set<String> ids=new HashSet<>();for(int i=0;i<a.size();i++){JsonNode n=a.get(i);String p="/actors/"+i;exact(n,p,Set.of("id","name","role","description"));String id=symbol(req(n,"id",p+"/id"),p+"/id");unique(ids,id,p);out.add(new Actor(id,text(n,"name",p+"/name",1,120,true,c),text(n,"role",p+"/role",1,240,true,c),text(n,"description",p+"/description",1,600,true,c)));}return out;}
    private static State state(JsonNode n,C c){exact(n,"/state",Set.of("counters","flags","sets"));JsonNode ca=reqArray(n,"counters","/state/counters"),fa=reqArray(n,"flags","/state/flags"),sa=reqArray(n,"sets","/state/sets");range(ca,0,Math.min(4,c.limits.maxCounters()),"/state/counters");range(fa,0,Math.min(12,c.limits.maxFlags()),"/state/flags");range(sa,0,Math.min(2,c.limits.maxSets()),"/state/sets");Set<String> ci=new HashSet<>(),fi=new HashSet<>(),si=new HashSet<>();List<Counter> counters=new ArrayList<>();List<Flag> flags=new ArrayList<>();List<FiniteSet> sets=new ArrayList<>();for(int i=0;i<ca.size();i++){JsonNode x=ca.get(i);String p="/state/counters/"+i;exact(x,p,Set.of("id","min","max","initial"));String id=symbol(req(x,"id",p+"/id"),p+"/id");unique(ci,id,p);int min=integer(x,"min",p+"/min"),max=integer(x,"max",p+"/max"),initial=integer(x,"initial",p+"/initial");if(min>=max||min<c.cap.counterMin()||max>c.cap.counterMax()||initial<min||initial>max)throw bad("BLUEPRINT_CAPABILITY_EXCEEDED",p,"Counter bounds are outside the supported range");counters.add(new Counter(id,min,max,initial));}for(int i=0;i<fa.size();i++){JsonNode x=fa.get(i);String p="/state/flags/"+i;exact(x,p,Set.of("id","initial"));String id=symbol(req(x,"id",p+"/id"),p+"/id");unique(fi,id,p);flags.add(new Flag(id,bool(x,"initial",p+"/initial")));}for(int i=0;i<sa.size();i++){JsonNode x=sa.get(i);String p="/state/sets/"+i;exact(x,p,Set.of("id","values","initial"));String id=symbol(req(x,"id",p+"/id"),p+"/id");unique(si,id,p);List<String> values=symbols(reqArray(x,"values",p+"/values"),p+"/values",1,Math.min(8,c.cap.maxSetValues()));List<String> initial=symbols(reqArray(x,"initial",p+"/initial"),p+"/initial",0,values.size());if(!values.containsAll(initial))throw bad("BLUEPRINT_VARIANT_INVALID",p+"/initial","Initial set values must be declared");sets.add(new FiniteSet(id,values,initial));}return new State(counters,flags,sets);}
    private static List<Objective> objectives(JsonNode a,C c){range(a,c.cap.minObjectives(),Math.min(8,c.cap.maxObjectives()),"/objectives");List<Objective> out=new ArrayList<>();Set<String> ids=new HashSet<>();for(int i=0;i<a.size();i++){JsonNode n=a.get(i);String p="/objectives/"+i;exact(n,p,Set.of("id","title","description","completeWhen"));String id=symbol(req(n,"id",p+"/id"),p+"/id");unique(ids,id,p);int[] count={0};out.add(new Objective(id,text(n,"title",p+"/title",1,120,true,c),text(n,"description",p+"/description",1,600,true,c),condition(req(n,"completeWhen",p+"/completeWhen"),p+"/completeWhen",1,count,c)));}return out;}
    private static List<Phase> phases(JsonNode a,C c){if(a.size()!=5)throw bad("BLUEPRINT_PHASE_INVALID","/phases","Exactly five phases are required");List<Phase> out=new ArrayList<>();for(int i=0;i<5;i++){JsonNode n=a.get(i);String p="/phases/"+i;exact(n,p,Set.of("kind","goal","development","transition","actorIds","objectiveIds"));PhaseKind k=en(n,"kind",PhaseKind.class,p+"/kind");if(k!=PhaseKind.values()[i])throw bad("BLUEPRINT_PHASE_INVALID",p+"/kind","Phases must use engine order");out.add(new Phase(k,text(n,"goal",p+"/goal",1,600,true,c),text(n,"development",p+"/development",1,600,true,c),text(n,"transition",p+"/transition",1,600,true,c),symbols(reqArray(n,"actorIds",p+"/actorIds"),p+"/actorIds",0,c.cap.maxActors()),symbols(reqArray(n,"objectiveIds",p+"/objectiveIds"),p+"/objectiveIds",0,c.cap.maxObjectives())));}return out;}
    private static List<Scene> scenes(JsonNode a,C c){range(a,c.limits.minScenes(),Math.min(24,c.limits.maxScenes()),"/scenes");List<Scene> out=new ArrayList<>();Set<String> ids=new HashSet<>();for(int i=0;i<a.size();i++){JsonNode n=a.get(i);String p="/scenes/"+i;if(!n.isObject())throw type(p);String kind=plainText(req(n,"kind",p+"/kind"),p+"/kind");String id=symbol(req(n,"id",p+"/id"),p+"/id");unique(ids,id,p);if(kind.equals("DECISION")){exact(n,p,Set.of("id","kind","phase","title","intent","actorIds","objectiveIds","choices"));PhaseKind phase=en(n,"phase",PhaseKind.class,p+"/phase");if(phase==PhaseKind.ENDING)throw bad("BLUEPRINT_PHASE_INVALID",p+"/phase","Decision scene cannot use ending phase");JsonNode choices=reqArray(n,"choices",p+"/choices");range(choices,1,Math.min(4,c.cap.maxChoicesPerScene()),p+"/choices");List<Choice> cs=new ArrayList<>();Set<String> choiceIds=new HashSet<>();for(int j=0;j<choices.size();j++){JsonNode x=choices.get(j);String q=p+"/choices/"+j;exact(x,q,Set.of("id","intent","destinationSceneId","requires","effects"));String cid=symbol(req(x,"id",q+"/id"),q+"/id");unique(choiceIds,cid,q);JsonNode r=req(x,"requires",q+"/requires");Condition condition=null;if(!r.isNull()){int[] count={0};condition=condition(r,q+"/requires",1,count,c);}JsonNode effects=reqArray(x,"effects",q+"/effects");range(effects,0,Math.min(6,c.limits.maxEffectsPerChoice()),q+"/effects");List<Effect> es=new ArrayList<>();for(int z=0;z<effects.size();z++)es.add(effect(effects.get(z),q+"/effects/"+z,c));cs.add(new Choice(cid,text(x,"intent",q+"/intent",1,600,true,c),symbol(req(x,"destinationSceneId",q+"/destinationSceneId"),q+"/destinationSceneId"),condition,es));}out.add(new DecisionScene(id,phase,text(n,"title",p+"/title",1,120,true,c),text(n,"intent",p+"/intent",1,600,true,c),symbols(reqArray(n,"actorIds",p+"/actorIds"),p+"/actorIds",0,c.cap.maxActors()),symbols(reqArray(n,"objectiveIds",p+"/objectiveIds"),p+"/objectiveIds",0,c.cap.maxObjectives()),cs));}else if(kind.equals("ENDING")){exact(n,p,Set.of("id","kind","phase","title","intent","actorIds","objectiveIds","outcomeId"));PhaseKind phase=en(n,"phase",PhaseKind.class,p+"/phase");if(phase!=PhaseKind.ENDING)throw bad("BLUEPRINT_PHASE_INVALID",p+"/phase","Ending scene must use ending phase");out.add(new EndingScene(id,phase,text(n,"title",p+"/title",1,120,true,c),text(n,"intent",p+"/intent",1,600,true,c),symbols(reqArray(n,"actorIds",p+"/actorIds"),p+"/actorIds",0,c.cap.maxActors()),symbols(reqArray(n,"objectiveIds",p+"/objectiveIds"),p+"/objectiveIds",0,c.cap.maxObjectives()),symbol(req(n,"outcomeId",p+"/outcomeId"),p+"/outcomeId")));}else throw bad("BLUEPRINT_VARIANT_INVALID",p,"Unsupported scene variant");}return out;}
    private static List<Outcome> outcomes(JsonNode a,C c){range(a,Math.max(2,c.cap.minEndings()),Math.min(4,c.cap.maxEndings()),"/outcomes");List<Outcome> out=new ArrayList<>();Set<String> ids=new HashSet<>();for(int i=0;i<a.size();i++){JsonNode n=a.get(i);String p="/outcomes/"+i;exact(n,p,Set.of("id","resultClass","title","description"));String id=symbol(req(n,"id",p+"/id"),p+"/id");unique(ids,id,p);out.add(new Outcome(id,en(n,"resultClass",ResultClass.class,p+"/resultClass"),text(n,"title",p+"/title",1,120,true,c),text(n,"description",p+"/description",1,600,true,c)));}return out;}
    private static Condition condition(JsonNode n,String p,int depth,int[] count,C c){if(depth>Math.min(4,c.limits.maxConditionDepth())||++count[0]>Math.min(32,c.cap.maxConditionNodes()))throw bad("BLUEPRINT_CAPABILITY_EXCEEDED",p,"Condition exceeds the supported complexity");String type=plainText(req(n,"type",p+"/type"),p+"/type");if(!CONDITION_TYPES.contains(type)||!c.limits.allowedConditions().contains(type))throw bad("BLUEPRINT_MECHANIC_UNSUPPORTED",p,"Condition operator is not enabled");return switch(type){case "COUNTER_AT_LEAST","COUNTER_AT_MOST","COUNTER_EQUALS"->{exact(n,p,Set.of("type","counter","value"));yield new CounterCondition(type,symbol(req(n,"counter",p+"/counter"),p+"/counter"),integer(n,"value",p+"/value"));}case "FLAG_IS"->{exact(n,p,Set.of("type","flag","value"));yield new FlagCondition(symbol(req(n,"flag",p+"/flag"),p+"/flag"),bool(n,"value",p+"/value"));}case "SET_CONTAINS"->{exact(n,p,Set.of("type","set","value"));yield new SetContainsCondition(symbol(req(n,"set",p+"/set"),p+"/set"),symbol(req(n,"value",p+"/value"),p+"/value"));}case "SET_SIZE_AT_LEAST"->{exact(n,p,Set.of("type","set","size"));int size=integer(n,"size",p+"/size");if(size<0)throw bad("BLUEPRINT_VARIANT_INVALID",p+"/size","Set size must be nonnegative");yield new SetSizeCondition(symbol(req(n,"set",p+"/set"),p+"/set"),size);}case "VISITED_SCENE"->{exact(n,p,Set.of("type","scene"));yield new VisitedSceneCondition(symbol(req(n,"scene",p+"/scene"),p+"/scene"));}case "ALL","ANY"->{exact(n,p,Set.of("type","conditions"));JsonNode a=reqArray(n,"conditions",p+"/conditions");range(a,1,16,p+"/conditions");List<Condition> list=new ArrayList<>();for(int i=0;i<a.size();i++)list.add(condition(a.get(i),p+"/conditions/"+i,depth+1,count,c));yield new CompositeCondition(type,list);}case "NOT"->{exact(n,p,Set.of("type","condition"));yield new NotCondition(condition(req(n,"condition",p+"/condition"),p+"/condition",depth+1,count,c));}default->throw bad("BLUEPRINT_MECHANIC_UNSUPPORTED",p,"Unsupported condition");};}
    private static Effect effect(JsonNode n,String p,C c){String type=plainText(req(n,"type",p+"/type"),p+"/type");if(!EFFECT_TYPES.contains(type)||!c.limits.allowedEffects().contains(type))throw bad("BLUEPRINT_MECHANIC_UNSUPPORTED",p,"Effect operator is not enabled");return switch(type){case "COUNTER_ADD"->{exact(n,p,Set.of("type","counter","delta"));int d=integer(n,"delta",p+"/delta");if(d==0||Math.abs((long)d)>c.cap.maxCounterDelta())throw bad("BLUEPRINT_CAPABILITY_EXCEEDED",p+"/delta","Counter delta exceeds the supported range");yield new CounterEffect(type,symbol(req(n,"counter",p+"/counter"),p+"/counter"),d);}case "COUNTER_SET"->{exact(n,p,Set.of("type","counter","value"));yield new CounterEffect(type,symbol(req(n,"counter",p+"/counter"),p+"/counter"),integer(n,"value",p+"/value"));}case "FLAG_SET"->{exact(n,p,Set.of("type","flag","value"));yield new FlagEffect(symbol(req(n,"flag",p+"/flag"),p+"/flag"),bool(n,"value",p+"/value"));}case "SET_ADD","SET_REMOVE"->{exact(n,p,Set.of("type","set","value"));yield new SetEffect(type,symbol(req(n,"set",p+"/set"),p+"/set"),symbol(req(n,"value",p+"/value"),p+"/value"));}default->throw bad("BLUEPRINT_MECHANIC_UNSUPPORTED",p,"Unsupported effect");};}

    private static void exact(JsonNode n,String p,Set<String> fields){if(n==null||!n.isObject())throw type(p);if(n.size()>20)throw bad("BLUEPRINT_COMPLEXITY_LIMIT",p,"Object has too many members");for(String f:fields)if(!n.has(f))throw bad("BLUEPRINT_FIELD_REQUIRED",p+"/"+f,"Required blueprint field is missing");for(String name:n.propertyNames())if(!fields.contains(name))throw bad("BLUEPRINT_UNKNOWN_FIELD",p,"Blueprint object contains an unknown field");}
    private static JsonNode req(JsonNode n,String field,String p){if(n==null||!n.isObject()||!n.has(field))throw bad("BLUEPRINT_FIELD_REQUIRED",p,"Required blueprint field is missing");JsonNode v=n.get(field);if(v==null)throw bad("BLUEPRINT_FIELD_REQUIRED",p,"Required blueprint field is missing");return v;}
    private static JsonNode reqArray(JsonNode n,String f,String p){JsonNode v=req(n,f,p);if(!v.isArray())throw type(p);return v;}
    private static int integer(JsonNode n,String f,String p){JsonNode v=req(n,f,p);if(!v.isIntegralNumber()||!v.canConvertToInt())throw type(p);return v.intValue();}
    private static boolean bool(JsonNode n,String f,String p){JsonNode v=req(n,f,p);if(!v.isBoolean())throw type(p);return v.booleanValue();}
    private static String plainText(JsonNode n,String p){if(!n.isTextual())throw type(p);return n.textValue();}
    private static String text(JsonNode n,String f,String p,int min,int max,boolean narrative,C c){String s=plainText(req(n,f,p),p).replace("\r\n","\n").replace('\r','\n');int cp=s.codePointCount(0,s.length());if(cp<min||cp>max||s.isBlank()||containsControl(s)||ACTIVE.matcher(s).find())throw bad("BLUEPRINT_TEXT_INVALID",p,"Blueprint text is invalid");if(narrative)c.textTotal+=cp;return s;}
    private static List<String> texts(JsonNode n,String f,String p,int min,int max,int len,C c){JsonNode a=reqArray(n,f,p);range(a,min,max,p);List<String> out=new ArrayList<>();for(int i=0;i<a.size();i++){JsonNode holder=JSON.createObjectNode().set("v",a.get(i));out.add(text(holder,"v",p+"/"+i,1,len,true,c));}return out;}
    private static String symbol(JsonNode n,String p){String s=plainText(n,p);if(!SYMBOL.matcher(s).matches())throw bad("BLUEPRINT_SYMBOL_INVALID",p,"Blueprint symbol is invalid");return s;}
    private static List<String> symbols(JsonNode a,String p,int min,int max){range(a,min,max,p);List<String> out=new ArrayList<>();Set<String> seen=new HashSet<>();for(int i=0;i<a.size();i++){String s=symbol(a.get(i),p+"/"+i);if(!seen.add(s))throw bad("BLUEPRINT_DECLARATION_DUPLICATE",p+"/"+i,"Blueprint list contains a duplicate symbol");out.add(s);}return out;}
    private static <E extends Enum<E>> E en(JsonNode n,String f,Class<E> type,String p){String s=plainText(req(n,f,p),p);try{return Enum.valueOf(type,s);}catch(IllegalArgumentException ex){throw bad("BLUEPRINT_VARIANT_INVALID",p,"Blueprint enum value is invalid");}}
    private static void unique(Set<String>s,String id,String p){if(!s.add(id))throw bad("BLUEPRINT_DECLARATION_DUPLICATE",p,"Blueprint declaration is duplicated");}
    private static void range(JsonNode a,int min,int max,String p){if(!a.isArray())throw type(p);if(a.size()<min||a.size()>max)throw bad("BLUEPRINT_CAPABILITY_EXCEEDED",p,"Blueprint list size is outside the supported range");}
    private static void complexity(JsonNode n,int depth,int[] count){if(depth>MAX_DEPTH||++count[0]>MAX_NODES)throw bad("BLUEPRINT_COMPLEXITY_LIMIT","","Blueprint JSON exceeds the supported complexity");if(n.isObject()||n.isArray())for(JsonNode child:n)complexity(child,depth+1,count);}
    private static boolean containsControl(String s){for(int i=0;i<s.length();i++){char ch=s.charAt(i);if(Character.isISOControl(ch)&&ch!='\n')return true;}return false;}
    private static boolean validUnicode(String s){for(int i=0;i<s.length();i++){char ch=s.charAt(i);if(Character.isHighSurrogate(ch)){if(i+1>=s.length()||!Character.isLowSurrogate(s.charAt(++i)))return false;}else if(Character.isLowSurrogate(ch))return false;}return true;}
    private static int utf8Length(String s){try{return Math.toIntExact(StandardCharsets.UTF_8.newEncoder().onMalformedInput(CodingErrorAction.REPORT).encode(java.nio.CharBuffer.wrap(s)).remaining());}catch(Exception ex){return Integer.MAX_VALUE;}}
    private static BlueprintException type(String p){return bad("BLUEPRINT_TYPE_INVALID",p,"Blueprint field has an invalid type");}
    private static BlueprintException bad(String c,String p,String m){return new BlueprintException(c,p,m);}
    private static BlueprintParseResult fail(String c,String p,String m){return BlueprintParseResult.rejected(new BlueprintIssue(c,"blueprint",p,m));}
    private static final class C{final ProfileCapabilities cap;final EffectiveGenerationConstraints limits;int textTotal;C(ValidatedGeneratorProfile p,ResolvedGamePreferences r,EffectiveGenerationConstraints l){cap=p.profile().capabilities();limits=l;}}
    private static final class BlueprintException extends RuntimeException{final String code,pointer,safeMessage;BlueprintException(String c,String p,String m){code=c;pointer=p;safeMessage=m;}}
}
